def digits(n):
    product = 1
    found_odd = False
    for digit in str(abs(n)):
        d = int(digit)
        if d % 2 == 1:
            product *= d
            found_odd = True
    return product if found_odd else 0

def sum_squares(lst):
    """
    This function will take a list. For all entries in the list, the function shall square the entry if its index is a multiple of 3 and will cube the entry if its index is a multiple of 4 and not a multiple of 3. The function will not change the entries in the list whose indexes are not a multiple of 3 or 4. The function shall then return the sum of all entries. 
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

def order_by_points(nums):
    def digit_sum(n):
        s = str(abs(n))
        # Negate the first digit
        total = -int(s[0])
        # Add the rest of the digits
        for d in s[1:]:
            total += int(d)
        return total
    return sorted(nums, key=digit_sum)

