def monotonic(nums):
    if not nums:
        return True
    increasing = decreasing = True
    for i in range(1, len(nums)):
        if nums[i] > nums[i-1]:
            decreasing = False
        if nums[i] < nums[i-1]:
            increasing = False
    return increasing or decreasing

def smallest_change(nums):
    changes = 0
    left, right = 0, len(nums) - 1
    while left < right:
        if nums[left] != nums[right]:
            changes += 1
        left += 1
        right -= 1
    return changes

def prime_length(s: str) -> bool:
    n = len(s)
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

